1	import type { EventType, TimelineLine } from "./types";
2	
3	export type AttackStatus =
4	  | "Devin processing"
5	  | "Devin fixing"
6	  | "Devin verifying"
7	  | "Devin deploying"
8	  | "Fix deployed";
9	
10	export interface AttackRecord {
11	  id: number;
12	  ts: number;
13	  nodeId: string;
14	  name: string;
15	  packetCount: number;
16	  status: AttackStatus;
17	}
18	
19	export interface AttackPacket {
20	  id: string;
21	  nodeId: string;
22	  frameType: string;
23	  match: string;
24	}
25	
26	const STATUS_BY_EVENT: Partial<Record<EventType, AttackStatus>> = {
27	  ANOMALY_DETECTED: "Devin processing",
28	  AGENT_ANALYZING: "Devin processing",
29	  FILTER_GENERATED: "Devin fixing",
30	  VERIFYING: "Devin verifying",
31	  VERIFY_FAILED: "Devin verifying",
32	  VERIFY_PASSED: "Devin verifying",
33	  OTA_DEPLOYING: "Devin deploying",
34	  DEPLOYED: "Fix deployed",
35	  FRAME_BLOCKED: "Fix deployed",
36	};
37	
38	export function selectFrameFeed(timeline: TimelineLine[], limit: number): TimelineLine[] {
39	  return timeline.slice(0, Math.max(0, limit));
40	}
41	
42	function parsePacketCount(text: string): number {
43	  const match = text.match(/([\d,]+)\s+(?:attack\s+)?frames?/i);
44	  return match ? Number(match[1].replaceAll(",", "")) : 1;
45	}
46	
47	function parseAttackClass(lines: TimelineLine[]): string | undefined {
48	  const generated = lines.find((line) => line.type === "FILTER_GENERATED");
49	  return generated?.text.match(/generated:\s*([a-z\d_ -]+)/i)?.[1]?.trim();
50	}
51	
52	function formatAttackName(value?: string | null): string {
53	  if (!value) return "Frame flood";
54	  const words = value.replaceAll("_", " ").trim();
55	  return words.charAt(0).toUpperCase() + words.slice(1);
56	}
57	
58	export function selectAttackHistory(timeline: TimelineLine[], activeAttack: string | null): AttackRecord[] {
59	  const anomalyIndexes = timeline.flatMap((line, index) => (line.type === "ANOMALY_DETECTED" ? [index] : []));
60	
61	  return anomalyIndexes.map((index, attackIndex) => {
62	    const segmentStart = attackIndex === 0 ? 0 : anomalyIndexes[attackIndex - 1] + 1;
63	    const anomaly = timeline[index];
64	    const related = timeline
65	      .slice(segmentStart, index + 1)
66	      .filter((line) => line.node_id === anomaly.node_id);
67	    const status = related.map((line) => STATUS_BY_EVENT[line.type]).find(Boolean) ?? "Devin processing";
68	    const attackClass = parseAttackClass(related) ?? (attackIndex === 0 ? activeAttack : null);
69	
70	    return {
71	      id: anomaly.id,
72	      ts: anomaly.ts,
73	      nodeId: anomaly.node_id ?? "system",
74	      name: formatAttackName(attackClass),
75	      packetCount: parsePacketCount(anomaly.text),
76	      status,
77	    };
78	  });
79	}
80	
81	export function selectAttackPackets(attack: AttackRecord, limit = 6): AttackPacket[] {
82	  const count = Math.min(Math.max(0, limit), attack.packetCount);
83	  const frameType = /deauth/i.test(attack.name) ? "Deauthentication" : "Matched frame";
84	
85	  return Array.from({ length: count }, (_, index) => ({
86	    id: `PKT-${String(attack.id).padStart(4, "0")}-${String(index + 1).padStart(3, "0")}`,
87	    nodeId: attack.nodeId,
88	    frameType,
89	    match: "Linked signature",
90	  }));
91	}
