220	void synchronizeRadioTarget() {
221	  if (WiFi.status() != WL_CONNECTED) {
222	    return;
223	  }
224	  radio.followAssociatedAccessPoint(static_cast<uint8_t>(WiFi.channel()),
225	                                    WiFi.BSSID());
226	}
