228	void serviceSerialCommands() {
229	  if constexpr (!app_config::kSerialSelfTest) {
230	    return;
231	  }
232	  while (Serial.available() > 0) {
233	    const char command = static_cast<char>(Serial.read());
234	    if (command == 't' || command == 'T' || command == 'd' ||
235	        command == 'D') {
236	      runSyntheticDeauthSelfTest();
237	    }
238	  }
239	}
