241	void writeLamp(bool on) {
242	  if (app_config::kLampPin < 0 || on == lampOutputOn) {
243	    return;
244	  }
245	  digitalWrite(app_config::kLampPin,
246	               on == app_config::kLampActiveHigh ? HIGH : LOW);
247	  lampOutputOn = on;
248	}
249	
250	void serviceLamp(uint32_t nowMs) { writeLamp(lampPattern.update(nowMs)); }
251	
252	void processCapturedFrame(const defense_sniffer::CapturedFrame& frame) {
253	  // The fixed target remains valid while the STA is temporarily disconnected,
254	  // so a deauth cannot disable local detection merely by breaking reporting.
255	  if (!radio.matchesTarget(frame)) {
256	    return;
257	  }
258	  traceCapturedFrame(frame);
259	
260	  defense_sniffer::FrameObservation observation;
261	  observation.observedAtMs = frame.observedAtMs;
262	  observation.observedAtUs = frame.observedAtUs;
263	  observation.rssi = frame.rssi;
264	  observation.channel = frame.channel;
265	  observation.subtype = frame.subtype;
266	  observation.bssid = frame.bssid;
267	  observation.sender = frame.sender;
268	  observation.bytes = frame.bytes;
269	  observation.length = frame.length;
270	  observation.originalLength = frame.originalLength;
271	
272	  defense_sniffer::AnomalyReport report;
273	  if (!detector.observe(observation, report)) {
274	    return;
275	  }
276	
277	  handleAcceptedReport(report, millis());
278	}
