.agents-section {
  padding: 92px max(24px, calc((100vw - 1320px) / 2)) 112px;
  border-top: var(--landing-border);
  background: #fff;
}

.section-intro {
  display: grid;
  grid-template-columns: 180px minmax(0, 1fr);
  align-items: start;
  margin-bottom: 40px;
}

.section-intro > span {
  padding-top: 7px;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.14em;
}

.section-intro h2 {
  max-width: 820px;
  margin: 0;
  font-size: clamp(34px, 5vw, 66px);
  line-height: 0.98;
  letter-spacing: -0.055em;
}

.agent-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 22px;
}

.agent-card {
  position: relative;
  min-width: 0;
  display: flex;
  flex-direction: column;
  padding: 0;
  overflow: hidden;
  border: var(--landing-border);
  background: #fff;
  box-shadow: var(--landing-shadow);
  color: #151515;
  cursor: pointer;
  text-align: left;
  transition: transform 160ms ease, box-shadow 160ms ease;
}

