  min-height: 46px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 16px;
  border-bottom: var(--landing-border);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.agent-card-top b {
  padding: 4px 6px;
  border: 1px solid #151515;
  background: #fff;
  font-size: 8px;
  text-transform: uppercase;
}

.agent-card[data-tone="orange"] .agent-card-top { background: #ff6422; }
