.agent-card[data-tone="command"] .agent-card-top { background: #ff9f7b; }

.agent-art {
  position: relative;
  height: clamp(240px, 28vw, 380px);
  display: block;
  overflow: hidden;
  border-bottom: var(--landing-border);
  background: #fff;
}

.agent-art img,
