const r=e=>{const b=e.getBoundingClientRect();return {x:Math.round(b.x),w:Math.round(b.width),h:Math.round(b.height)};};
const lead=document.querySelector('.command-lead');
const art=document.querySelector('.command-lead-art');
const name=document.querySelector('.command-lead-copy strong');
const sec=document.querySelector('.agents-section');
JSON.stringify({
  name:name?.textContent,
  eyebrow:document.querySelector('.command-lead-top span')?.textContent,
  badge:document.querySelector('.command-lead-top b')?.textContent,
  lead:r(lead), art:r(art),
  centered: Math.abs((r(lead).x + r(lead).w/2) - (r(sec).x + r(sec).w/2)) < 3,
  sectionW:r(sec).w
});

(() => {
  const rect=e=>{const b=e.getBoundingClientRect();return {x:Math.round(b.x),w:Math.round(b.width),h:Math.round(b.height)};};
  const lead=document.querySelector('.command-lead');
  const art=document.querySelector('.command-lead-art');
  const name=document.querySelector('.command-lead-copy strong');
  const sec=document.querySelector('.agents-section');
  return JSON.stringify({
    name:name?.textContent,
    eyebrow:document.querySelector('.command-lead-top span')?.textContent,
    badge:document.querySelector('.command-lead-top b')?.textContent,
    lead:rect(lead), art:rect(art),
    centered: Math.abs((rect(lead).x + rect(lead).w/2) - (rect(sec).x + rect(sec).w/2)) < 3,
    sectionW:rect(sec).w
  });
})();
